def summarize_tasks(tasks: list[dict], status: str | None = None) -> dict:
    if status is None:
        selected_tasks = tasks
    else:
        selected_tasks = [task for task in tasks if task["status"] == status]
    return {
        "count": len(selected_tasks),
        "total_duration": sum(task["duration"] for task in selected_tasks),
    }
